        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var roundKey = 'round' + (idx + 1);
            var roundTitle = t(roundKey + '_title');
            var roundBriefing = t(roundKey + '_briefing');
            var roundEvent = t(roundKey + '_event');

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = '<strong>' + roundTitle + ' (' + t('week_label') + ' ' + ((idx * 2) + 1) + '-' + ((idx * 2) + 2) + ')</strong><br><br>' + roundBriefing;

            var eventEl = document.getElementById('eventAlert');
            if (eventEl && roundEvent) {
                eventEl.innerHTML = roundEvent;
                eventEl.style.display = 'block';
            }
        }
    }

